S=/private/tmp/claude-501/-Users-kunabel-workspace-MercedesExperience/76543b44-616b-4206-b493-b9c88af3200a/scratchpad && cat > $S/emit.mjs <<'EOF'
// Turns scratch de/<slug>.json into stops/<slug>/de.js, checking its text leaves match the English skeleton.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
const R = "/Users/kunabel/workspace/MercedesExperience";
const { leaves, skeleton } = await import(`${R}/tests/unit/helpers.mjs`);
const S = process.argv[2];
const head = "// German text for car.js, merged over it by loadCar (lib/app/i18n.js): same shape, strings only, null keeps the original.\n";
const js = (v, ind = "") => {
  const n = ind + "  ";
  if (v === null) return "null";
  if (typeof v === "string") return JSON.stringify(v);
  if (Array.isArray(v)) {
    if (v.every(x => x === null || (x && typeof x === "object" && Object.keys(x).length === 1 && typeof Object.values(x)[0] === "string" && JSON.stringify(x).length < 90)))
      return `[${v.map(x => (x === null ? "null" : `{ ${Object.keys(x)[0]}: ${JSON.stringify(Object.values(x)[0])} }`)).join(", ")}]`;
    return `[\n${v.map(x => n + js(x, n)).join(",\n")},\n${ind}]`;
  }
  return `{\n${Object.entries(v).map(([k, x]) => `${n}${/^[A-Za-z_]\w*$/.test(k) ? k : JSON.stringify(k)}: ${js(x, n)}`).join(",\n")},\n${ind}}`;
};
let bad = 0;
for (const slug of process.argv.slice(3)) {
  const de = JSON.parse(readFileSync(`${S}/de/${slug}.json`, "utf8"));
  const car = (await import(`${R}/stops/${slug}/car.js`)).default;
  const want = leaves(skeleton(car)).map(([p]) => p).sort().join("\n"), got = leaves(de).map(([p]) => p).sort().join("\n");
  if (want !== got) { bad++; const w = new Set(want.split("\n")), g = new Set(got.split("\n")); console.log(slug, "missing:", [...w].filter(p => !g.has(p)), "extra:", [...g].filter(p => !w.has(p))); continue; }
  const dec = leaves(de).filter(([, v]) => /\d\.\d/.test(v.replace(/SEL 6\.3|SLC 5\.0|\b2\.[35]-16/g, "")));
  if (dec.length) { bad++; console.log(slug, "decimal point:", dec); continue; }
  writeFileSync(`${R}/stops/${slug}/de.js`, `${head}export default ${js(de)};\n`);
  console.log(slug, "ok");
}
process.exit(bad ? 1 : 0);
EOF
